from review import card,save,DATE

i='TCS-3222';_,c=card(i);refs=c['references'];refs[0]['locator']='Definitions 1, 2 and 4; Sections 1.3–1.5; Section 2 field convention; Section 4, question 1; Appendix F, Definition 33 and Theorem 34.'
refs.append(dict(id='journal2024',title='Weighted Sum-of-Squares Lower Bounds for Univariate Polynomials Imply VP ≠ VNP',authors='Pranjal Dutta; Nitin Saxena; Thomas Thierauf',year=2024,url='https://doi.org/10.1007/s00037-024-00249-0',pdf_url='https://www.cse.iitk.ac.in/users/nitin/papers/sos-jcc.pdf',locator='Computational Complexity 33, article 3, published 16 April 2024. Author manuscript: Definition 1.2, Section 2 (explicitness and hitting-set generators), Theorem 3.2, and Section 7, question 1.'))
issue='The original implication is recoverable, including the quantitative SOS hypothesis and deterministic blackbox PIT target. A finished benchmark must fix the field and coefficient encoding/cost conventions for the implication: the conference version defaults to Q (or large-characteristic finite fields), whereas the journal discussion also uses C. In particular, a Q-valued SOS lower bound must not silently become a lower bound allowing complex decompositions. The conference’s uniform polynomial-time coefficient-bit access and the journal’s weaker nonuniform counting-class explicitness must also be kept distinct. The statement below preserves the conference hypothesis; exact arithmetic versus bit-cost conventions for the PIT construction still need to be fixed.'
save(i,dict(title='Does weighted SOS hardness imply polynomial-time blackbox PIT?',formal='Does the existence of an explicit SOS-hard polynomial family in the sense of the ITCS 2021 source imply a deterministic polynomial-time blackbox polynomial identity test for general arithmetic circuits of polynomially bounded degree? The original hardness hypothesis is: for some fixed number N≥1 of variables, an explicit family (f_d) of degree d satisfies S_F(f_d)≥c d^{N(1/2+ε(d))} for all sufficiently large d, where c>0 is constant, ε(d)→0, and ε(d)/√(log log d/log d)→∞. The desired conclusion is full polynomial-time derandomization, not just subexponential or quasipolynomial time. Field, coefficient and exact cost conventions are not yet fixed to a single self-contained model.',definitions='For a polynomial f over a field F of characteristic different from two, S_F(f) is the minimum of ∑ᵢ|supp(gᵢ)| over all finite identities f=∑ᵢcᵢgᵢ² with cᵢ∈F and gᵢ∈F[x₁,…,x_N]. supp(g) is the set of monomials with nonzero coefficient. Weights may be negative when F is ordered; this is a weighted algebraic sum of squares, not a nonnegative-polynomial certificate. There is no bound on the number of summands or on their degrees in the definition of S_F. A monomial appearing in several gᵢ is counted separately in each. The source’s explicitness condition requires coefficient encodings of length polynomial in d and a uniform algorithm that, on binary d, a monomial exponent tuple and a coefficient-bit position, returns that bit in time polynomial in log d for valid positions. The field and bit encoding must be specified to make this exact. N is fixed independently of d; constants in the hardness and explicitness bounds may depend on the family. Arithmetic circuits here are finite directed acyclic computations with variables and field constants at the leaves and binary addition and multiplication gates. Polynomial identity testing asks whether the resulting formal polynomial is identically zero. In the blackbox version, the algorithm knows bounds on the circuit size s, number of variables n and degree D, and accesses only exact evaluations. The requested polynomial-time dependence is in s,n,D, equivalently in a common bound t≥max{s,n,D}; it does not require polynomial time in log D. A hitting set is a finite set H of evaluation points such that every nonzero polynomial in the bounded circuit class is nonzero at some point of H. A deterministic construction of a polynomial-size hitting set in polynomial time would meet the blackbox target once field representation and operation costs are fixed.',question_type='yes_no',answer_criterion='Prove or refute the stated implication with the conference hardness hypothesis and a precisely fixed field/computational model. A positive answer must obtain deterministic polynomial-time blackbox PIT for unrestricted arithmetic circuits with the stated size and degree bounds. A sum-of-cubes hypothesis, a larger fixed hardness exponent, a change of the field allowed in decompositions, or merely subexponential/quasipolynomial PIT does not establish the requested implication.',context_blocks=[dict(title='Hardness is measured in a restricted algebraic representation',text='S_F counts the monomials needed inside a weighted sum of squares, irrespective of whether f has a short general circuit. The source asks whether a slight explicit improvement over the square-root support scale already forces full derandomization of general polynomial identity testing.',citation='primary'),dict(title='The proved square and cube consequences differ',text='The conference paper derives circuit lower bounds and subexponential blackbox PIT from its SOS-hardness assumption. A stronger constant-exponent assumption gives quasipolynomial PIT. Its separate sum-of-cubes hardness assumption yields polynomial-time blackbox PIT; the open question asks for that last conclusion from SOS hardness itself.',citation='primary'),dict(title='The journal version keeps the question open',text='The 2024 journal treatment adds results and retains the same first concluding question. Its terminology for explicit families is broader than the conference version’s polynomial-time coefficient-bit condition. This card keeps the original condition rather than silently changing the antecedent.',citation='journal2024'),dict(title='Remaining specification',text=issue)],why='Would connect lower bounds for a restricted univariate or constant-variate polynomial representation to complete derandomization of identity testing for general arithmetic circuits.',references=refs,progress=[dict(date='2021',text='The source proves weaker PIT derandomization from SOS hardness and polynomial-time PIT from a different sum-of-cubes hypothesis, then asks whether SOS hardness alone suffices.',citation='primary'),dict(date='2024-04-16',text='The journal version retains the implication as its first concluding open question, with extended lower-bound and border-complexity results.',citation='journal2024')],status='source_open',status_note='Read the conference definitions and target, the expanded author manuscript, and the 2024 journal version’s definitions and conclusion. Checked the publisher record and searched later work through 12 September 2026. No resolution was found; the field and exact computational conventions remain unfinished.',model_self_contained=False,requires_context=True,statement_review=dict(reviewed_on=DATE,status='needs_specification',remaining_issue=issue,notes=['Recovered weighted support-sum hardness and the full blackbox-PIT consequence.']),importance=dict(score=c['importance']['score'],method='editorial',reason='A direct bridge between restricted algebraic lower bounds and a central derandomization problem. Existing score retained.',assessed_on=DATE),review_note='Defined weighted SOS size, the subconstant hardness threshold, explicit coefficient access and the blackbox target. Separated squares from cubes and the conference/journal conventions.',working_summary=dict(sentences=['Weighted SOS complexity counts monomials inside a representation as a field-weighted sum of polynomial squares.','The source assumes an explicit constant-variate family whose complexity grows slightly faster than the basic square-root scale.','It asks whether that hypothesis gives a deterministic polynomial-time blackbox identity test for general arithmetic circuits.','The known SOS consequences are weaker, and the 2024 journal version still poses the full derandomization question.','Field, coefficient representation and operation-cost conventions must be finalized without replacing the original explicitness hypothesis.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','journal2024'])),notes=['Recovered the weighted rather than nonnegative SOS model.','Restored the exact subconstant epsilon threshold and fixed variable count.','Specified that the desired PIT result is deterministic, blackbox and polynomial in degree as well as size.','Checked the 2024 journal version and retained its distinction from the conference’s explicitness condition.','Recorded the remaining field and computation conventions.'],checked_sources=[r['url'] for r in refs]+['https://www.cse.iitk.ac.in/users/nitin/papers/sos_journal.pdf'],state='improved_unfinished')
